export declare const SDK_FORMATS: readonly ["typedoc", "docfx", "javadoc", "sphinx", "phpdoc", "go"];
export type SdkFormat = (typeof SDK_FORMATS)[number];
export declare const SDK_SYMBOL_KINDS: readonly ["package", "class", "interface", "enum", "function", "type", "variable", "method", "property"];
export type SdkSymbolKind = (typeof SDK_SYMBOL_KINDS)[number];
export type SdkTarget = {
    format?: SdkFormat;
    source?: string;
    kind: SdkSymbolKind;
    name: string;
    parent?: string;
    namespace?: string;
};
export type ResolvedSdkTarget = SdkTarget & {
    format: SdkFormat;
    source: string;
};
